const FOOD_ELIXIRS=[
  {name:"Fish Porridge",cat:"Food — Ice Resistance",detail:"Bestes Preis-Leistungs-Gericht für Kältezonen. Rezept: 1 Fish (oder 2 Fish Fillet) + 1 Lentils (oder Beans/Barley/Wheat/Peas) + 1 Salt + 3 Water = Health +240, Ice Resistance Lv 4 für 1 Min. Resistance-Level und Dauer bleiben über alle Stufen fix, nur HP steigt. Basisversion auch für Renee's Request nötig.",loc:"Feld-Kochtopf an jedem Lagerfeuer. Quelle: VGC, PC Gamer, Gamer Guides",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_fishporridge_0001.webp"},
  {name:"Clear Soup",cat:"Food — Ice Resistance",detail:"Günstiges frühes Ice-Resistance-Gericht. Rezept: 1 Meat + 1 Lentils (oder Beans/Barley/Wheat/Peas) + 1 Water = Health +180, Ice Resistance Lv 2 für 30 Sek. Level und Dauer fix über alle Stufen, nur HP steigt mit höherer Kochstufe.",loc:"Feld-Kochtopf. Quelle: VGC, game8",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_whiteradishsoup_0001.webp"},
  {name:"Meat Soup",cat:"Food — Ice Resistance",detail:"Günstige fleischbasierte Ice-Resistance-Alternative zu Fish Porridge. Rezept: 4 Meat + 1 Lentils (oder Beans/Barley/Wheat/Peas) + 1 Salt + 3 Water = Health +280, Ice Resistance Lv 4 für 1 Min.",loc:"Feld-Kochtopf. Quelle: VGC",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_meatgukbap_0001.webp"},
  {name:"Braised Ribs",cat:"Food — Ice Resistance",detail:"Heilung, Spirit und Ice Resistance in einem Gericht. Rezept: 4 Meat + 2 Onion (oder Flax/Cucumber/Turnip/Beet) + 2 Berry + 3 Water = Health +260, Spirit +24, Ice Resistance Lv 4 für 1 Min.",loc:"Feld-Kochtopf. Quelle: VGC",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_chickencutlet_0002.webp"},
  {name:"Fishball Soup",cat:"Food — Ice Resistance",detail:"HP-stärkeres Fischgericht für Kältezonen. Rezept: 1 Fish (oder 2 Fish Fillet) + 2 Lentils (oder Beans/Barley/Wheat/Peas) + 1 Onion (oder Flax/Cucumber/Turnip/Beet) + 1 Salt + 3 Water = Health +340, Ice Resistance Lv 4 für 1 Min.",loc:"Feld-Kochtopf. Quelle: VGC",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_eomuktang_0001.webp"},
  {name:"Vegetable and Seafood Porridge",cat:"Food — Ice Resistance",detail:"Spirit-lastiges Erkundungsessen mit Ice Resistance. Rezept: 1 Fish (oder 2 Fish Fillet) + 2 Lentils (oder Beans/Barley/Wheat/Peas) + 3 Onion (oder Flax/Cucumber/Turnip/Beet) + 3 Water = Health +240, Spirit +22, Ice Resistance Lv 4 für 1 Min.",loc:"Feld-Kochtopf. Quelle: VGC",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_antlerporridge_0003.webp"},
  {name:"Fruit Punch",cat:"Food — Fire Resistance",detail:"Günstigste verlässliche Fire-Resistance-Quelle. Rezept: 1 Berry + 1 Barley + 1 Water = Health +140, Spirit +12, Fire Resistance Lv 4 für 1 Min. Billiger Top-up vor Feuer-Bossen.",loc:"Feld-Kochtopf. Quelle: VGC",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_hwachae_0001.webp"},
  {name:"Pan-Fried Marinated Meat",cat:"Food — Fire Resistance",detail:"Starkes gegrilltes Fire-Resistance-Gericht. Rezept: 3 Meat + 2 Berry + 2 Onion (oder Flax/Cucumber/Turnip/Beet) + 3 Cooking Oil = Health +260, Spirit +24, Fire Resistance Lv 4 für 1 Min. Gut für Feuer-Bosse und Lava-/Abyss-Zonen.",loc:"Feld-Grill an jedem Lagerfeuer. Quelle: VGC",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_bulgogi_0001.webp"},
  {name:"Battered Seafood",cat:"Food — Fire Resistance",detail:"Gegrillte Fire-Resistance- und Spirit-Option. Rezept: 2 Fish (oder 4 Fish Fillet) + 2 Onion (oder Flax/Cucumber/Turnip/Beet) + 2 Egg + 3 Cooking Oil = Health +260, Spirit +24, Fire Resistance Lv 4 für 1 Min.",loc:"Feld-Grill. Quelle: VGC",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_seafoodpancake_0001.webp"},
  {name:"Vegetable Rice Cake",cat:"Food — Fire Resistance",detail:"Bestes Fire-Resistance-Gericht rein aus farmbarem Gemüse und Ei. Rezept: 4 Onion (oder Flax/Cucumber/Turnip/Beet) + 2 Berry + 1 Egg + 2 Salt = Health +240, Spirit +22, Fire Resistance Lv 4 für 1 Min.",loc:"Feld-Grill. Quelle: VGC",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_vegetable_tteok_0001.webp"},
  {name:"Salt-Roasted Bird Meat",cat:"Food — Fire Resistance",detail:"Günstigste frühe Fire Resistance. Rezept: 1 Bird Meat + 1 Salt = Health +120, Fire Resistance Lv 2 für 30 Sek. Schneller Top-up aus gejagten Vögeln.",loc:"Feld-Grill. Quelle: VGC",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_chicken_0002.webp"},
  {name:"Battered Harvest Roll",cat:"Food — Fire Resistance",detail:"Hochwertiges Fire-Resistance-Grillgericht. Rezept: 2 Harvest Roll + 1 Fine Meat + 2 Egg + 2 Cooking Oil. Basis ca. Spirit +62 und Fire Resistance +6 (ca. 1 Min 30 Sek) laut Item-Datenbanken; die Hearty-Stufe wird mit ca. +1000 HP / +92 Spirit / Fire Resistance +6 angegeben (Einzelquelle, als ungefähr behandeln). HP skaliert mit Stufe, Resistance bleibt fix.",loc:"Rezept bei einem Inn-Innkeeper lernbar (genannt: Delesyia Inn). Quelle: Gamer Guides, gaming.tools; Hearty-Werte method.gg",miss:false,conf:"medium",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_egg_gimbap_0001.webp"},
  {name:"Freya's Elixir",cat:"Elixir — Angriff/Tempo",detail:"Wichtigstes OFFENSIV-Elixir vor Bossen. Tier-Leiter: Lesser = Attack +5 (5 Min); Standard = Attack +7 (10 Min); Greater = Attack +10 (15 Min). Am Cauldron gebraut (Attack-Reagenz + Katalysator + Empty Bottle).",loc:"Formeln über Welt-Loot/Händler/Nebenquests. Die Forschung 'Plant Combination Research' (Shai-Apotheker in Pororin) schaltet laut Beschreibung diverse Elixier-Rezepte frei — welche genau, ist nicht dokumentiert. Die Mission 'Defeat the Crimson Nightmare' (Quest 'Continuing Concern') gibt 1x Freya's Elixir (dazu 2x Apollonia's Lesser und 2x Meliara's Lesser), 'Head to Hernand' (Quest 'Unknown Space') ein weiteres; fertig auch bei Conrad/Vincent für 300 Kupfer. Quelle: questlog-API, gaming.tools",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_potion_0004_index01_r.webp"},
  {name:"Meliara's Lesser Elixir",cat:"Elixir — Angriff/Tempo",detail:"Max Health +75 und Attack Speed Lv 1 für 5 Min - anhaltende Überlebensfähigkeit plus Offense aus dem Basis-Cauldron. Rezept: 2x Lesser-Health-Reagenz + 1x Lesser-Katalysator + 1x Empty Bottle. Greater-Stufe gibt Max Health +225 / Attack Speed Lv 3 für 15 Min.",loc:"Formel bei Mudridge Cabin (nördlich von Pororin Woods, Hernand; Schiebebild-Rätsel lösen). Quelle: TheGamer, gaming.tools",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_potion_0004_index06_r.webp"},
  {name:"Apollonia's Elixir",cat:"Elixir — Verteidigung",detail:"Defensive Named-Elixir-Linie - Defense Up, KEIN Offensiv-Buff. Tier-Leiter: Lesser = Defense +10 (5 Min); Common/Standard = Defense +20 (10 Min); Superior/Greater = Defense +30 (15 Min). Am Cauldron gebraut (Defense-Reagenz + Katalysator + Empty Bottle).",loc:"Formeln über Welt-Loot/Händler. Die Forschung 'Plant Combination Research' (Shai-Apotheker in Pororin) schaltet laut Beschreibung diverse Elixier-Rezepte frei — welche genau, ist nicht dokumentiert. Quelle: questlog-API, gaming.tools",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_potion_0004_index05_r.webp"},
  {name:"Haiden's Lesser Elixir",cat:"Elixir — Spirit/Stamina",detail:"Ignoriert für 4 Sekunden den Spirit-Verbrauch - erlaubt eine kurze Kette aus Spirit-kostenden Spezialmoves. Cauldron-Rezept: 2x niedriges Reagenz + 1x Lesser Catalyst (Iron Ore, Copper Ore, Stone o.ä.) + 1x Empty Bottle.",loc:"Formel in Hernand, im Haus mit Trank- und Alchemiegläsern am Eingang; sie liegt auf dem Tisch in der Raummitte. Quelle: Fextralife; Rezeptwerte: gaming.tools, TheGamer",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_potion_0004_index09_r.webp"},
  {name:"Astrid's Lesser Elixir",cat:"Elixir — Spirit/Stamina",detail:"Ignoriert für 4 Sekunden den Stamina-Verbrauch - ein Schub unbegrenztes Sprinten/Ausweichen/Repositionieren. Cauldron-Rezept: 2x niedriges Stamina-Reagenz + 1x Lesser Catalyst + 1x Empty Bottle.",loc:"Formel im Back-Alley-Shop in Pailune (nach einem Punkt der Hauptstory verfügbar). Quelle: TheGamer, gaming.tools",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_prefab_cd_t0000_potion_0004_index12_r.webp"},
  {name:"Palmar Pill",cat:"Elixir — Wiederbelebung",detail:"Selbst-Wiederbelebung: bei Tod sofortiges Revive mit 30% der max. Health für einen weiteren Versuch - wichtiger Panik-Knopf für harte Bosse. Cauldron-Rezept: 2x Water + 15x Medicinal Herb derselben Sorte (31 Sorten kommen in Frage).",loc:"Formel in der Shadow's Whisper Cave nördlich von Hernand Town (Felsspalte in der Klippe), auf einem Tisch bei der Hexe Sylvia; die Höhle gehört zur Quest 'Refined Power' (ab Kapitel 2). Die Pille selbst auch bei Lacey (Lacey's Secret Shop) für 360 Kupfer. Quelle: game8, gaming.tools, questlog-API",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_cd_t0000_revivalpill_0002.webp"},
  {name:"Refined Palmar Pill",cat:"Elixir — Wiederbelebung",detail:"Verbesserte Selbst-Wiederbelebung: Revive mit 100% der max. Health (statt 30% bei der normalen Palmar Pill) - großer Überlebens-Item für Boss-Kämpfe. Cauldron-Rezept: 1x Water + 1x Palmar Leaf + 1x Palmar Beetle + 1x High-Grade Medicinal Herb (Ginseng, Long Horn oder Bear's Gallbladder).",loc:"Formel nur als sehr seltener Drop vom Tariv Sorcerer verzeichnet; der kursierende Fundort 'Ascetic's Rest' (Abyss, Kapitel 9) ist unbelegt. Die Pille selbst bei Lacey (Lacey's Secret Shop) für 1080 Kupfer, aus seltenen Drops, der Dispatch-Mission 'Reachwood Ruins Dispatch' und Truhen. Quelle: gaming.tools, questlog-API",miss:false,conf:"high",icon:"/assets/_sprites/itemicon_cd_t0000_revivalpill_0001.webp"}
];
